/**
 * opencode-plugboard: an OpenAI-compatible HTTP endpoint served from inside an OpenCode V2
 * server, backed by the server's own providers.
 *
 * Install in the GLOBAL OpenCode config. OpenCode loads the plugin once per Location:
 *   - everywhere, a generation asks to join the process-wide listener (src/runtime.ts); an
 *     accepted one can serve requests (a confirmed app-directory Location is preferred, else the
 *     newest), a rejected one does nothing at all;
 *   - every accepted generation also registers the context hook, the agent deny and the seed
 *     tools, but all three are no-ops until a request has confirmed, asynchronously, that the
 *     Location is a plugboard app directory (`.../opencode-plugboard/<app>/`, real path strictly
 *     inside the data root; `ensureBackend` in src/runtime.ts). Until then, and in every other
 *     project, nothing is rewritten.
 *
 * Freeze safety: this effect only registers and returns. It makes no `ctx` call that waits on
 * location readiness, touches no filesystem and never blocks, and its finalizer is synchronous
 * and calls nothing on `ctx` (a plugin effect that blocked once froze every prompt in a project).
 * The event pump starts lazily from request handling. See docs/architecture.md.
 */

import { Plugin } from "@opencode/plugin/effect"
import { Effect } from "effect"
import { appSessionLimits, parseOptions } from "./src/config.js"
import { personaOf } from "./src/models.js"
import { errorMessage, logError } from "./src/log.js"
import { withFallbacks } from "./src/fallback.js"
import { withStopSequences } from "./src/stop.js"
import { withBudgets } from "./src/budgets.js"
import { withLimits } from "./src/limits.js"
import { createOpenAiRoute } from "./src/openai/route.js"
import {
  ensureBackend,
  ensurePump,
  loadServingCatalog,
  processBreaker,
  processBudgets,
  processKeys,
  processLimits,
  processMetrics,
  processUsage,
  registerGeneration,
  setConfigError,
  sessionStore,
  withResponseCache,
} from "./src/runtime.js"
import { createSessionCaller } from "./src/session/caller.js"
import type { ImageFetch } from "./src/session/media.js"
import { createAffinity } from "./src/session/affinity.js"
import { installSessionHooks } from "./src/session/context.js"
import { createHistoryPort, createKeepAliveHost, createSessionPort, createStoragePort, loadCatalog } from "./src/session/host.js"
import { keepAliveIntervalMs, keepAliveLoop } from "./src/keepalive.js"
import { createKeyStore } from "./src/keys.js"
import { createResponseStore } from "./src/responses/state.js"
import { createFileStore } from "./src/files/state.js"
import { createRecordStore } from "./src/record-store.js"
import { usageHandlers, UsageRpc } from "./src/rpc.js"
import { createUsageRecorder, withUsage } from "./src/usage.js"
import { hostVersion } from "./src/version.js"

export default Plugin.define({
  id: "opencode-plugboard",
  effect: (ctx) =>
    Effect.gen(function* () {
      let options: ReturnType<typeof parseOptions>
      try {
        options = parseOptions(ctx.options)
      } catch (error) {
        // Invalid options fail this setup, so the host lists the plugin as `failed` with the message
        // (opencode packages/core/src/plugin.ts: a failed setup becomes slot.error, then the state).
        // Nothing is registered, so the Location stays inert. The same message goes to the error log,
        // and to `/plugboard/status` and `/readyz` while a listener from an earlier good generation serves (#159).
        const message = errorMessage(error)
        setConfigError(message)
        logError("options.invalid", { error: message })
        return yield* Effect.die(new Error(`plugboard options are invalid: ${message}`))
      }
      setConfigError(undefined)

      // ---- every Location: join the shared listener (sync registration only).
      const sessions = sessionStore()
      // Started lazily from request handling (handler, catalog load); never from setup.
      const startPump = () => ensurePump(() => ctx.event.subscribe())
      const ownCatalog = () => loadCatalog(ctx)
      // Request handling only: an agent lookup scoped to another directory makes the host build that
      // Location, which loads this plugin there. Plugin setup never calls it.
      const bootLocation = (directory: string) => Effect.runPromise(ctx.agent.list({ location: { directory } }))
      const callerDeps = {
        port: createSessionPort(ctx),
        sessions,
        maxTools: options.maxTools,
        apps: options.apps,
        persona: (model: string) => personaOf(options, model),
        remoteImages: options.remoteImages,
        promptCache: options.promptCache,
        affinity: createAffinity({ storage: createStoragePort(ctx) }),
        hideFromList: options.sessions.hideFromList,
        requestTimeoutMs: options.requestTimeoutMs,
        ...(options.silenceMs === undefined ? {} : { silenceMs: options.silenceMs }),
        ...(options.metrics ? { metrics: processMetrics } : {}),
        onUsageMissing: (app: string) => {
          if (options.metrics) processMetrics().usageMissing(app, "disconnect")
        },
        onImageFetch: (fetched: ImageFetch) => {
          if (options.metrics) processMetrics().imageFetch(fetched)
        },
        // The readiness gate the caller awaits before creating a session (fails closed: 503 `backend_unavailable`).
        ensureBackend: (app: string, signal: AbortSignal) => ensureBackend(app, signal, bootLocation),
      }
      // The catalog comes from the preferred accepted generation (a data-root Location when there is
      // one), not from whichever Location registered last; this generation's own is the fallback.
      const servingCatalog = async () => {
        startPump()
        return loadServingCatalog(ownCatalog)
      }
      const limits = options.limits
      // Usage (src/usage.ts): built from closures only; it reads and writes storage from request handling.
      const usage = options.usage.enabled
        ? createUsageRecorder({ state: processUsage(), storage: createStoragePort(ctx), loadCatalog: servingCatalog, retentionDays: options.usage.retentionDays })
        : undefined
      const handle = createOpenAiRoute({
        options,
        // The host's own version (`ctx.app`), shown on `/plugboard/status` (#347).
        opencodeVersion: hostVersion(ctx.app?.version),
        // Usage is outermost, so it records the answer the client gets (src/usage.ts).
        // Caps are outside the fallbacks, so one request takes one slot even when it falls back (src/limits.ts).
        // Aliases written as a list retry the next target before the first output (src/fallback.ts).
        // The response cache is outside budgets and limits: a hit spends nothing, takes no slot and counts toward no
        // rate window, and never reaches a provider (src/cache.ts). Only a miss is budgeted and limited.
        caller: withUsage(
          withResponseCache(
            // Budgets sit outside the limiter, so a budget refusal never takes a slot (src/budgets.ts).
            withBudgets(
              withLimits(
                // Stop sequences are applied to the answer where the host run ends, so a cached answer is the one cut (src/stop.ts).
                withFallbacks(
                  withStopSequences(createSessionCaller(callerDeps), (app) => {
                    if (options.metrics) processMetrics().usageMissing(app, "stop")
                  }),
                  {
                    options,
                    loadCatalog: servingCatalog,
                    breaker: processBreaker(),
                    onFallback: (app) => {
                      if (options.metrics) processMetrics().fallback(app)
                      usage?.fallback(app)
                    },
                    onCooldown: (event, app) => {
                      if (options.metrics) processMetrics().breaker(app, event)
                    },
                  },
                ),
                () => limits,
                processLimits(),
                {
                  onLimited: (app, reason) => {
                    if (options.metrics) processMetrics().limited(app, reason)
                    usage?.limited(app)
                  },
                },
              ),
              options.budgets,
              usage,
              processBudgets(),
              {
                onRefused: (app) => {
                  if (options.metrics) processMetrics().limited(app, "budget")
                  usage?.limited(app)
                },
              },
            ),
            options,
          ),
          usage,
        ),
        loadCatalog: servingCatalog,
        usage,
        // Runtime app keys (#55): read from storage on the first authentication, cached on the runtime.
        keys: createKeyStore({ state: processKeys(), storage: createStoragePort(ctx) }),
        // Stored Responses (src/responses/state.ts): read and written from request handling, on the same host storage.
        responses: createResponseStore({ storage: createStoragePort(ctx) }),
        // Uploaded files (src/files/state.ts, since next): same host storage, request handling only.
        files: createFileStore({ storage: createStoragePort(ctx) }),
        // Exchange records (src/record-store.ts, #586): same host storage, written and read from request handling only.
        records: createRecordStore({ storage: createStoragePort(ctx) }),
        // The prompt a count reads (persona, server tools): the same port, persona lookup and backend gate as the session caller (#201).
        session: callerDeps,
      })
      const registration = registerGeneration({
        listen: options.listen,
        options,
        // The host's string, compared with the real path `ensureBackend` confirms; no filesystem access here.
        directory: ctx.location.directory,
        // Rebuild the transforms below once a request has confirmed this Location as an app directory.
        refresh: () => Effect.runPromise(Effect.all([ctx.agent.reload(), ctx.tool.reload()], { discard: true })),
        // Host handles for indexing and pruning request sessions; only called from request handling.
        history: { port: createHistoryPort(ctx), limits: options.sessions, apps: appSessionLimits(options) },
        handler: (request, response) => {
          startPump()
          handle(request, response).catch((error) => {
            logError("request.unhandled", { error: errorMessage(error) })
            if (response.headersSent) return void response.end()
            response.writeHead(500, { "content-type": "application/json" })
            response.end(JSON.stringify({ error: { message: "Internal server error", type: "server_error" } }))
          })
        },
        loadCatalog: ownCatalog,
      })
      yield* Effect.addFinalizer(() => Effect.sync(() => registration.dispose()))

      // ---- a rejected generation (different options or `listen`, foreign runtime) serves nothing and installs nothing.
      if (!registration.accepted) return

      // ---- the keep-alive (#310): forked into the plugin scope, never awaited. Only the generation holding the lease ticks (src/keepalive.ts).
      if (options.keepAlive !== false)
        yield* Effect.forkScoped(
          keepAliveLoop({
            host: createKeepAliveHost(ctx, createStoragePort(ctx)),
            intervalMs: keepAliveIntervalMs(),
            isOwner: registration.keepAliveOwner,
          }),
        )

      // ---- the usage RPC (src/rpc.ts): a synchronous registration; its handler reads the store from request time only.
      // Its error channel is `unknown` in the host, so a failed registration is logged and the plugin keeps loading.
      if (usage)
        yield* ctx.rpc.register(UsageRpc, usageHandlers(usage)).pipe(Effect.catch((error) => Effect.sync(() => logError("rpc.register_failed", { rpc: UsageRpc.id, error: errorMessage(error) }))))

      // ---- the context hook, the agent deny and the seed tools. Ownership of the Location is only
      // known after an asynchronous check (`ensureBackend`), so all three are no-ops until
      // `registration.confirmed()`: in real projects nothing is ever added or rewritten.
      yield* installSessionHooks(ctx, { maxTools: options.maxTools, apps: options.apps, sessions, active: registration.confirmed })
      registration.ready()
    }),
})

#!/usr/bin/env bun
// `bunx opencode-plugboard init`: the command line entry. The logic is in src/cli.ts.
import { homedir } from "node:os"
import { runCli } from "../src/cli.js"
import { PACKAGE_VERSION } from "../src/version.js"

process.exitCode = runCli(process.argv.slice(2), {
  out: (text) => process.stdout.write(text),
  err: (text) => process.stderr.write(text),
  env: process.env,
  home: homedir(),
  version: PACKAGE_VERSION,
})

/**
 * The `opencode-plugboard` command line (`bunx opencode-plugboard init`): writes the plugin entry into an OpenCode config
 * so the first request needs no manual steps. Not loaded by the plugin; `bin/opencode-plugboard.ts` is the entry.
 *
 * `init` edits the config as JSONC with `jsonc-parser`, so comments, formatting and every other key stay as they were.
 * It pins the running package version, generates one app key, and never replaces an existing plugboard entry without `--force`.
 * A config it creates is mode 0600 (and a directory it creates 0700), because the file holds the key; an existing file keeps its mode.
 */

import { randomBytes } from "node:crypto"
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs"
import { dirname, join, resolve } from "node:path"
import { parseArgs } from "node:util"
import { applyEdits, modify, parse, printParseErrorCode, type ParseError } from "jsonc-parser"
import { ALL_MODELS, DEFAULT_PORT, isAppName } from "./config.js"
import { parseModelRef } from "./models.js"

const PACKAGE = "opencode-plugboard"
const TROUBLESHOOTING = "https://jjjermiah.github.io/opencode-plugboard/install#if-it-does-not-answer"
const FORMAT = { tabSize: 2, insertSpaces: true, eol: "\n" } as const

/** What the CLI needs from the process, so tests can run it against temp dirs with fixed output and keys. */
export interface CliEnv {
  readonly out: (text: string) => void
  readonly err: (text: string) => void
  readonly env: Readonly<Record<string, string | undefined>>
  readonly home: string
  /** The running package version; `init` pins it. */
  readonly version: string | undefined
  /** A fresh app key. Defaults to 32 random bytes, base64url, with a `pb_` prefix. */
  readonly newKey?: () => string
}

export const USAGE = `Usage: opencode-plugboard init [options]

Adds plugboard to your OpenCode config, with one app key and every connected model allowed.

Options:
  --app <name>       App name for the key (default: my-app)
  --fast <model>     Also add the alias "fast", for example anthropic/claude-haiku-4-5
  --config <path>    Config file to edit (default: ~/.config/opencode/opencode.jsonc)
  --dry-run          Print the change as a diff and write nothing
  --force            Replace an existing plugboard entry (it gets a new key)
  -h, --help         Show this help
`

class CliError extends Error {}

const defaultKey = (): string => `pb_${randomBytes(32).toString("base64url")}`

/** `opencode.jsonc`, or `opencode.json` when only that exists, in the OpenCode config directory. */
function defaultConfigPath(env: CliEnv): string {
  const dir = join(env.env.XDG_CONFIG_HOME || join(env.home, ".config"), "opencode")
  const jsonc = join(dir, "opencode.jsonc")
  const json = join(dir, "opencode.json")
  return !existsSync(jsonc) && existsSync(json) ? json : jsonc
}

/** The file's text, or "" when it does not exist. */
function fileText(path: string): string {
  if (!existsSync(path)) return ""
  try {
    return readFileSync(path, "utf8")
  } catch (error) {
    throw new CliError(`cannot read ${path}: ${(error as Error).message}`)
  }
}

const isPlugboard = (entry: unknown): boolean => {
  const name = typeof entry === "string" ? entry : typeof entry === "object" && entry !== null ? (entry as { package?: unknown }).package : undefined
  return typeof name === "string" && (name === PACKAGE || name.startsWith(`${PACKAGE}@`))
}

/** The lines of `before` and `after` as a unified-style diff (whole-file context is not needed: the files are small). */
export function lineDiff(before: string, after: string, label: string): string {
  const split = (text: string): string[] => (text === "" ? [] : text.endsWith("\n") ? text.slice(0, -1).split("\n") : text.split("\n"))
  const a = split(before)
  const b = split(after)
  const lcs = Array.from({ length: a.length + 1 }, () => new Array<number>(b.length + 1).fill(0))
  for (let i = a.length - 1; i >= 0; i--) for (let j = b.length - 1; j >= 0; j--) lcs[i]![j] = a[i] === b[j] ? lcs[i + 1]![j + 1]! + 1 : Math.max(lcs[i + 1]![j]!, lcs[i]![j + 1]!)
  const lines = [`--- ${label}`, `+++ ${label}`]
  let i = 0
  let j = 0
  while (i < a.length || j < b.length) {
    if (i < a.length && j < b.length && a[i] === b[j]) {
      lines.push(` ${a[i]}`)
      i++
      j++
    } else if (i < a.length && (j === b.length || lcs[i + 1]![j]! >= lcs[i]![j + 1]!)) lines.push(`-${a[i++]}`)
    else lines.push(`+${b[j++]}`)
  }
  return `${lines.join("\n")}\n`
}

interface InitFlags {
  readonly app: string
  readonly fast?: string
  readonly config?: string
  readonly dryRun: boolean
  readonly force: boolean
}

function flagsOf(args: string[]): InitFlags | "help" {
  let v: { app?: string; fast?: string; config?: string; "dry-run"?: boolean; force?: boolean; help?: boolean }
  try {
    v = parseArgs({
      args,
      allowPositionals: false,
      options: { app: { type: "string" }, fast: { type: "string" }, config: { type: "string" }, "dry-run": { type: "boolean" }, force: { type: "boolean" }, help: { type: "boolean", short: "h" } },
    }).values
  } catch (error) {
    throw new CliError(`${(error as Error).message}\n\n${USAGE}`)
  }
  if (v.help) return "help"
  const app = v.app ?? "my-app"
  if (!isAppName(app)) throw new CliError(`--app \`${app}\` must be lower case letters, digits and hyphens (at most 255 characters)`)
  const fast = v.fast
  if (fast !== undefined) {
    const ref = parseModelRef(fast)
    if (!ref || fast.includes("*") || /\s/.test(fast))
      throw new CliError(`--fast \`${fast}\` must be one model, written provider/model or provider/model#variant (for example anthropic/claude-haiku-4-5)`)
  }
  return { app, ...(fast === undefined ? {} : { fast }), ...(v.config === undefined ? {} : { config: v.config }), dryRun: v["dry-run"] === true, force: v.force === true }
}

/** The text of the config after the plugin entry is added (or replaced, with `replace`), edited in place as JSONC. */
function withEntry(text: string, entry: unknown, force: boolean, path: string): { text: string; replaced: boolean } {
  const source = text.trim() === "" ? "{}\n" : text
  const errors: ParseError[] = []
  const root = parse(source, errors, { allowTrailingComma: true }) as unknown
  if (errors.length > 0) throw new CliError(`${path} is not valid JSONC (${printParseErrorCode(errors[0]!.error)} at offset ${errors[0]!.offset}); fix it, then run init again. Nothing was written.`)
  if (typeof root !== "object" || root === null || Array.isArray(root)) throw new CliError(`${path} must hold a JSON object. Nothing was written.`)
  const plugins = (root as { plugins?: unknown }).plugins
  if (plugins !== undefined && !Array.isArray(plugins)) throw new CliError(`\`plugins\` in ${path} must be an array. Nothing was written.`)
  const existing = (plugins ?? []).findIndex(isPlugboard)
  if (existing >= 0 && !force) throw new CliError(`${path} already has a plugboard entry. Nothing was written; add --force to replace it (the replacement gets a new key), or edit the entry by hand.`)
  const edits =
    plugins === undefined
      ? modify(source, ["plugins"], [entry], { formattingOptions: FORMAT })
      : existing >= 0
        ? modify(source, ["plugins", existing], entry, { formattingOptions: FORMAT })
        : modify(source, ["plugins", plugins.length], entry, { formattingOptions: FORMAT, isArrayInsertion: true })
  return { text: applyEdits(source, edits), replaced: existing >= 0 }
}

/** `init`. Returns the process exit code. */
export function runInit(args: string[], cli: CliEnv): number {
  try {
    const flags = flagsOf(args)
    if (flags === "help") {
      cli.out(USAGE)
      return 0
    }
    if (cli.version === undefined) throw new CliError("cannot read this package's version, so the plugin cannot be pinned")
    const path = resolve(flags.config ?? defaultConfigPath(cli))
    const before = fileText(path)
    // A dry run writes nothing, so it shows a placeholder instead of a key nobody will ever use.
    const key = flags.dryRun ? "<new key, shown when written>" : (cli.newKey ?? defaultKey)()
    const entry = {
      package: `${PACKAGE}@${cli.version}`,
      options: { keys: { [flags.app]: key }, models: ALL_MODELS, ...(flags.fast === undefined ? {} : { aliases: { fast: flags.fast } }) },
    }
    const { text, replaced } = withEntry(before, entry, flags.force, path)
    if (flags.dryRun) {
      cli.out(lineDiff(before, text, path))
      cli.out(replaced ? "Dry run: the existing plugboard entry would be replaced. Nothing was written.\n" : "Dry run: nothing was written.\n")
      return 0
    }
    try {
      // The file holds the app key: a new file is the owner's alone, and so is a directory made for it. An existing file keeps its own mode.
      mkdirSync(dirname(path), { recursive: true, mode: 0o700 })
      writeFileSync(path, text.endsWith("\n") ? text : `${text}\n`, existsSync(path) ? undefined : { mode: 0o600 })
    } catch (error) {
      throw new CliError(`cannot write ${path}: ${(error as Error).message}`)
    }
    const base = `http://127.0.0.1:${DEFAULT_PORT}/v1`
    const chatModel = flags.fast === undefined ? "<model id from step 2>" : "fast"
    cli.out(
      [
        `${replaced ? "Replaced" : "Added"} ${PACKAGE}@${cli.version} in ${path}.`,
        "",
        `App key for \`${flags.app}\` (it is also saved in that file; keep the file private):`,
        `  ${key}`,
        "",
        "1. Restart OpenCode, then touch the server once so it loads the plugin (run this again after every restart):",
        "  opencode api get /api/agent",
        "",
        "2. List the models you can use:",
        `  curl -s ${base}/models -H "Authorization: Bearer ${key}"`,
        "",
        flags.fast === undefined ? "3. Call one (replace <model id from step 2> with an id from that list):" : "3. Call the alias `fast`:",
        `  curl -s ${base}/chat/completions -H "Authorization: Bearer ${key}" -H "Content-Type: application/json" -d '{"model": "${chatModel}", "messages": [{"role": "user", "content": "reply with exactly: pong"}]}'`,
        "",
        `No answer on ${DEFAULT_PORT}? See ${TROUBLESHOOTING}`,
        "",
      ].join("\n"),
    )
    return 0
  } catch (error) {
    if (!(error instanceof CliError)) throw error
    cli.err(`${error.message}\n`)
    return 1
  }
}

/** The command line: `init` is the only command. Returns the process exit code. */
export function runCli(argv: string[], cli: CliEnv): number {
  const [command, ...rest] = argv
  if (command === "init") return runInit(rest, cli)
  if (command === undefined || command === "-h" || command === "--help" || command === "help") {
    cli.out(USAGE)
    return command === undefined ? 2 : 0
  }
  cli.err(`Unknown command \`${command}\`.\n\n${USAGE}`)
  return 2
}

/*
 * plugboard dashboard (#141). Plain browser script, no build step, served as /plugboard/dashboard/app.js.
 *
 * Data comes only from GET /plugboard/usage (the Usage tab) and GET /v1/models (the Models tab), with the key the
 * person typed (kept in sessionStorage). Every value that came from the server (app names, model ids) reaches the
 * page through textContent or attributes; nothing here writes markup from a string. The page sends no inline
 * script or style (see page.ts), so nothing here sets a style attribute either.
 */
(function () {
  "use strict";

  var KEY_STORAGE = "plugboard.usage.key";
  var MODELS_KEY_STORAGE = "plugboard.models.key";
  var DAYS_STORAGE = "plugboard.dashboard.days";
  var RANGES = [1, 7, 30, 90];
  var MODEL_ROWS = 10;
  var TAG_ROWS = 20;
  var CATALOG_ROWS = 100;
  var dark = window.matchMedia("(prefers-color-scheme: dark)");

  var state = {
    tab: location.hash === "#models" ? "models" : "usage",
    days: 7,
    report: null,
    reportDays: 7,
